38	int base64_value(char c) {
39	    if (c >= 'A' && c <= 'Z') return c - 'A';
40	    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
41	    if (c >= '0' && c <= '9') return c - '0' + 52;
42	    if (c == '+') return 62;
43	    if (c == '/') return 63;
44	    return -1;
45	}
46	
47	bool is_base64_token(char c) {
48	    return base64_value(c) >= 0 || c == '=';
49	}
