219	bool format_name(X509_NAME* name, std::string& out) {
220	    int count = X509_NAME_entry_count(name);
221	    int previous_set = -1;
222	    for (int i = 0; i < count; ++i) {
223	        X509_NAME_ENTRY* entry = X509_NAME_get_entry(name, i);
224	        if (entry == nullptr) return false;
225	        ASN1_OBJECT* object = X509_NAME_ENTRY_get_object(entry);
226	        ASN1_STRING* asn1_value = X509_NAME_ENTRY_get_data(entry);
227	        if (object == nullptr || asn1_value == nullptr) return false;
228	
229	        const char* short_name = nullptr;
230	        std::string dotted_oid;
231	        int nid = OBJ_obj2nid(object);
232	        if (nid != NID_undef) short_name = OBJ_nid2sn(nid);
233	        if (short_name == nullptr) {
234	            // Size the buffer from the dotted form itself: an unknown OID's
235	            // decimal text can be arbitrarily long, so a fixed buffer would
236	            // silently clip its tail and make distinct OIDs look identical.
237	            int oid_length = OBJ_obj2txt(nullptr, 0, object, 1);
238	            if (oid_length <= 0) return false;
239	            dotted_oid.resize(static_cast<size_t>(oid_length));
240	            int written = OBJ_obj2txt(dotted_oid.data(),
241	                                      static_cast<int>(dotted_oid.size()) + 1,
242	                                      object, 1);
243	            if (written != oid_length) return false;
244	            short_name = dotted_oid.c_str();
245	        }
246	
247	        unsigned char* utf8_raw = nullptr;
248	        int utf8_length = ASN1_STRING_to_UTF8(&utf8_raw, asn1_value);
249	        if (utf8_length < 0) return false;
250	        std::unique_ptr<unsigned char, OpenSSLFree> utf8_guard(
251	            utf8_raw, OpenSSLFree{});
252	        std::string value(reinterpret_cast<char*>(utf8_raw),
253	                          static_cast<size_t>(utf8_length));
254	        if (!is_valid_utf8(value)) value = latin1_to_utf8(value);
255	
256	        int current_set = X509_NAME_ENTRY_set(entry);
257	        if (i > 0) {
258	            out.append(current_set == previous_set ? "+" : ", ");
259	        }
260	        out.append(short_name);
261	        out.push_back('=');
262	        out.append(escape_dn_value(value));
263	        previous_set = current_set;
264	    }
265	    return true;
266	}
